<main class="content"><div class="catalog-grid"><?php foreach([['roles','Roles de usuario',$roles],['subjects','Asignaturas',$subjects],['tabulator_groups','Grupos tabuladores',$groups],['tabulator_subgroups','Subgrupos tabuladores',$subgroups]] as [$type,$label,$items]):?><section class="panel"><h2><?=e($label)?></h2><form class="inline-form" method="post" action="<?=url('/admin/catalogos/guardar')?>"><?=csrf_field()?><input type="hidden" name="type" value="<?=$type?>"><input required name="name" placeholder="Nuevo nombre"><?php if($type==='tabulator_subgroups'):?><select name="group_id" required><?php foreach($groups as $g):?><option value="<?=$g['id']?>"><?=e($g['name'])?></option><?php endforeach;?></select><?php endif;?><button class="primary">Agregar</button></form><ul class="clean-list"><?php foreach($items as $i):?><li><b>#<?=$i['id']?></b> <?=e($i['name'])?></li><?php endforeach;?></ul></section><?php endforeach;?></div></main>

